int main(){float f[16]={0,.5f,1,1.5f,2,3,4,6,-0.f,-.5f,-1,-1.5f,-2,-3,-4,-6},sf[128];for(int i=0;i<128;i++){int e=i>>3,m=i&7;sf[i]=e?ldexpf(1.f+float(m)/8.f,e-7):float(m)/512.f;}CK(cudaMemcpyToSymbol(E2,f,64));CK(cudaMemcpyToSymbol(SCALE,sf,512));std::mt19937 rng(20261014);std::vector<uint8_t>w(M*K/2),x(N*K/2),sc(N*GROUPS);int c3[3]={0,1,3};for(int r=0;r<M;r++)for(int k=0;k<K;k++)w[r*(K/2)+k/2]|=uint8_t(c3[rng()%3]|(c3[rng()%3]<<2))<<(4*(k&1));for(auto&v:x)v=uint8_t(rng());for(int i=0;i<N*GROUPS;i++)sc[i]=uint8_t((i*37+11)%127);uint8_t*dw,*dx,*ds;CK(cudaMalloc(&dw,w.size()));CK(cudaMalloc(&dx,x.size()));CK(cudaMalloc(&ds,sc.size()));CK(cudaMemcpy(dw,w.data(),w.size(),cudaMemcpyHostToDevice));CK(cudaMemcpy(dx,x.data(),x.size(),cudaMemcpyHostToDevice));CK(cudaMemcpy(ds,sc.data(),sc.size(),cudaMemcpyHostToDevice));uint32_t*di;unsigned long long*de;CK(cudaMalloc(&di,C*2*12*4));CK(cudaMalloc(&de,20*8));CK(cudaMemset(de,0,20*8));probe<<<dim3(8,2),256>>>(dw,dx,ds,di,de);CK(cudaGetLastError());CK(cudaDeviceSynchronize());std::vector<uint32_t>image(C*2*12);unsigned long long errors[20];CK(cudaMemcpy(image.data(),di,image.size()*4,cudaMemcpyDeviceToHost));CK(cudaMemcpy(errors,de,20*8,cudaMemcpyDeviceToHost));FILE*fout=fopen("mixed-k64-reduction-image.bin","wb");if(!fout||fwrite(image.data(),4,image.size(),fout)!=image.size())return 4;fclose(fout);const char*names[]={"mixed-k64-weights.bin","mixed-k64-activations.bin","mixed-k64-scales.bin"};std::vector<uint8_t>*ins[]={&w,&x,&sc};for(int a=0;a<3;a++){fout=fopen(names[a],"wb");if(!fout||fwrite(ins[a]->data(),1,ins[a]->size(),fout)!=ins[a]->size())return 4;fclose(fout);}printf("{\"status\":\"observed\",\"source_K\":128,\"native_K\":64,\"source_groups_per_native_instruction\":4,\"rules\":[\"sequential_groups\",\"pairwise_groups_plus_C\",\"exact_double_groups_plus_C\",\"sequential_halves\",\"sequential_scaled_products\"],\"nonzero_word_differences\":[");for(int i=0;i<20;i++)printf("%s%llu",i?",":"",errors[i]);printf("],\"checks_pe